<style>.hmn-ea-form{max-width:650px;margin:20px auto;padding:28px;background:#fff;border:1px solid #e4e7ec;border-radius:18px;font-family:Tahoma,sans-serif;box-shadow:0 8px 30px rgba(20,30,50,.06)}.hmn-ea-form label{display:grid;gap:7px;margin:0 0 14px;font-weight:700;font-size:13px}.hmn-ea-form input,.hmn-ea-form select{width:100%;padding:12px;border:1px solid #d4d9e2;border-radius:9px;font:inherit;background:#fff}.hmn-ea-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.hmn-ea-step{display:none}.hmn-ea-step.is-active{display:block}.hmn-ea-step h3{margin:4px 0 20px;font-size:18px}.hmn-ea-steps{display:flex;align-items:center;justify-content:center;margin:0 0 28px;color:#98a1b2;font-size:12px}.hmn-ea-steps span{display:grid;place-items:center;width:78px;height:30px;border-radius:16px;background:#f1f3f7}.hmn-ea-steps span.is-active{background:#5b4cf0;color:#fff}.hmn-ea-steps i{width:34px;height:1px;background:#d9dee8}.hmn-ea-otp,.hmn-ea-actions{display:flex;gap:10px;align-items:center}.hmn-ea-otp input{flex:1}.hmn-ea-send-otp,.hmn-ea-next,.hmn-ea-submit,.hmn-ea-back{border:0;border-radius:9px;padding:12px 16px;font:inherit;cursor:pointer}.hmn-ea-send-otp,.hmn-ea-next,.hmn-ea-submit{background:#5b4cf0;color:#fff}.hmn-ea-next,.hmn-ea-submit{margin-top:8px;min-width:130px}.hmn-ea-back{background:#f0f2f6;color:#3b4352}.hmn-ea-actions{justify-content:space-between;margin-top:18px}.hmn-ea-calendar{margin-top:18px;border:1px solid #e5e8ef;border-radius:12px;padding:14px}.hmn-ea-cal-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.hmn-ea-cal-head button{border:0;background:#f3f1ff;color:#5b4cf0;border-radius:8px;width:34px;height:30px;font-size:22px;cursor:pointer}.hmn-ea-weekdays,.hmn-ea-days{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;gap:4px}.hmn-ea-weekdays{color:#8490a2;font-size:11px;margin-bottom:5px}.hmn-ea-days button{border:0;background:transparent;border-radius:8px;height:35px;cursor:pointer;font:inherit}.hmn-ea-days button:not(:disabled):hover{background:#eeeaff;color:#5140ea}.hmn-ea-days button.is-selected{background:#5b4cf0;color:#fff}.hmn-ea-days button:disabled{color:#c8ced8;cursor:not-allowed}.hmn-ea-slots{margin-top:16px;min-height:52px}.hmn-ea-slot-list{display:flex;flex-wrap:wrap;gap:8px}.hmn-ea-slot{border:1px solid #d9ddef;background:#fff;border-radius:8px;padding:9px 12px;cursor:pointer;font:inherit}.hmn-ea-slot.is-selected{border-color:#5b4cf0;background:#eeeaff;color:#4635d2}.hmn-ea-summary{background:#f7f8fb;border-radius:12px;padding:16px;line-height:2}.hmn-ea-message{min-height:1.5em;margin:15px 0 0}.hmn-ea-message.is-error{color:#b42318}.hmn-ea-message.is-success{color:#067647}.hmn-ea-form .hmn-crm-send-otp{display:none!important}@media(max-width:480px){.hmn-ea-grid{grid-template-columns:1fr}.hmn-ea-steps i{width:12px}.hmn-ea-steps span{width:70px}.hmn-ea-otp{align-items:stretch;flex-direction:column}}</style>
<script>(function(){var f=document.currentScript.previousElementSibling.previousElementSibling,ajax=<?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>,nonce=<?php echo wp_json_encode( wp_create_nonce( 'hmn_ea_booking' ) ); ?>,today=<?php echo wp_json_encode( wp_date( 'Y-m-d' ) ); ?>,service=f.elements.service_id,provider=f.elements.provider_id,date=f.elements.appointment_date,chosenTime='',cal={};function req(a,d){d.action=a;d.nonce=nonce;return fetch(ajax,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(d)}).then(r=>r.json()).then(r=>{if(!r.success)throw Error(r.data&&r.data.message||'خطا');return r.data})}function msg(t,c){var e=f.querySelector('.hmn-ea-message');e.textContent=t;e.className='hmn-ea-message '+(c||'')}function fill(e,x,p){e.innerHTML='<option value="">'+p+'</option>';x.forEach(i=>{var o=document.createElement('option');o.value=i.id;o.textContent=i.firstName?i.firstName+' '+i.lastName:i.name;e.appendChild(o)})}function step(n){f.querySelectorAll('.hmn-ea-step').forEach(x=>x.classList.toggle('is-active',+x.dataset.step===n));f.querySelectorAll('.hmn-ea-steps span').forEach((x,i)=>x.classList.toggle('is-active',i===n-1));window.scrollTo({top:f.getBoundingClientRect().top+window.scrollY-100,behavior:'smooth'})}function g2j(d){var gy=d.getFullYear(),gm=d.getMonth()+1,gd=d.getDate(),gdm=[0,31,59,90,120,151,181,212,243,273,304,334],jy=gy>1600?979:0;gy-=gy>1600?1600:621;var gy2=gm>2?gy+1:gy,days=365*gy+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)-80+gd+gdm[gm-1];jy+=33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365}var jm=days<186?1+Math.floor(days/31):7+Math.floor((days-186)/30),jd=1+(days<186?days%31:(days-186)%30);return{y:jy,m:jm,d:jd}}function j2g(y,m,d){var gy=y+621;if(m>10||(m===10&&d>10))gy++;var x=new Date(gy,2,21);x.setDate(x.getDate()+(m<=6?(m-1)*31:186+(m-7)*30)+d-1);return x}function monthDays(m){return m<=6?31:m<=11?30:29}function renderCal(){var names=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],head=f.querySelector('.hmn-ea-cal-head strong'),box=f.querySelector('.hmn-ea-days');head.textContent=names[cal.m-1]+' '+cal.y;box.innerHTML='';var first=j2g(cal.y,cal.m,1),offset=(first.getDay()+1)%7;for(var i=0;i<offset;i++)box.appendChild(document.createElement('span'));for(var d=1;d<=monthDays(cal.m);d++){let jd=d,iso=j2g(cal.y,cal.m,d).toISOString().slice(0,10),b=document.createElement('button');b.type='button';b.textContent=d;b.dataset.date=iso;b.disabled=iso<today;if(iso===date.value)b.className='is-selected';b.addEventListener('click',function(){date.value=this.dataset.date;chosenTime='';renderCal();loadSlots()});box.appendChild(b)}}function loadSlots(){var box=f.querySelector('.hmn-ea-slots');if(!service.value||!provider.value||!date.value){box.innerHTML='<p>ابتدا نوع سرویس، پزشک و روز را انتخاب کنید.</p>';return}box.innerHTML='<p>در حال دریافت ساعت‌های آزاد…</p>';req('hmn_ea_slots',{service_id:service.value,provider_id:provider.value,date:date.value}).then(d=>{if(!d.slots.length){box.innerHTML='<p>برای این روز ساعت آزادی وجود ندارد.</p>';return}box.innerHTML='<div class="hmn-ea-slot-list"></div>';var list=box.firstChild;d.slots.forEach(t=>{var b=document.createElement('button');b.type='button';b.className='hmn-ea-slot';b.textContent=t;b.addEventListener('click',function(){chosenTime=t;list.querySelectorAll('button').forEach(x=>x.classList.toggle('is-selected',x===b))});list.appendChild(b)})}).catch(e=>{box.innerHTML='<p class="is-error">'+e.message+'</p>';msg(e.message,'is-error')})}req('hmn_ea_bootstrap',{}).then(d=>{fill(service,d.services,'انتخاب نوع سرویس');f._providers=d.providers||[]}).catch(e=>msg(e.message,'is-error'));var now=g2j(new Date());cal={y:now.y,m:now.m};renderCal();f.querySelectorAll('[data-cal]').forEach(b=>b.addEventListener('click',function(){if(this.dataset.cal==='next'){cal.m++;if(cal.m>12){cal.m=1;cal.y++}}else{cal.m--;if(cal.m<1){cal.m=12;cal.y--}}renderCal()}));service.addEventListener('change',()=>{var x=(f._providers||[]).filter(p=>!p.services||p.services.indexOf(+service.value)>=0);if(provider.tagName==='SELECT')fill(provider,x,'انتخاب پزشک');chosenTime='';loadSlots()});if(provider.tagName==='SELECT')provider.addEventListener('change',()=>{chosenTime='';loadSlots()});f.querySelector('.hmn-ea-send-otp').addEventListener('click',function(){var b=this,p=f.elements.user_phone.value;if(!/^09\d{9}$/.test(p)){msg('شماره تلفن معتبر نیست.','is-error');return}b.disabled=true;req('hmn_send_otp',{user_phone:p}).then(()=>msg('کد تأیید ارسال شد.','is-success')).catch(e=>msg(e.message,'is-error')).finally(()=>setTimeout(()=>b.disabled=false,120000))});f.querySelectorAll('.hmn-ea-next')[0].addEventListener('click',()=>{if(!f.elements.first_name.value||!f.elements.last_name.value||!/^09\d{9}$/.test(f.elements.user_phone.value)||!f.elements.otp_code.value){msg('ابتدا مشخصات و کد تأیید را کامل کنید.','is-error');return}step(2)});f.querySelectorAll('.hmn-ea-next')[1].addEventListener('click',()=>{if(!service.value||!provider.value||!date.value||!chosenTime){msg('سرویس، پزشک، روز و ساعت را انتخاب کنید.','is-error');return}var sn=service.options[service.selectedIndex].text,pn=provider.tagName==='SELECT'?provider.options[provider.selectedIndex].text:'پزشک مجموعه';f.querySelector('.hmn-ea-summary').innerHTML='نام: '+f.elements.first_name.value+' '+f.elements.last_name.value+'<br>سرویس: '+sn+'<br>پزشک: '+pn+'<br>زمان: '+date.value+' — '+chosenTime;step(3)});f.querySelectorAll('.hmn-ea-back').forEach((b,i)=>b.addEventListener('click',()=>step(i===0?1:2)));f.addEventListener('submit',e=>{e.preventDefault();if(!chosenTime)return;var b=f.querySelector('.hmn-ea-submit');b.disabled=true;msg('در حال ثبت نوبت…');req('hmn_ea_book',{first_name:f.elements.first_name.value,last_name:f.elements.last_name.value,user_phone:f.elements.user_phone.value,otp_code:f.elements.otp_code.value,service_id:service.value,provider_id:provider.value,appointment_date:date.value,appointment_time:chosenTime}).then(r=>{msg('نوبت شما با موفقیت ثبت شد. کد پیگیری: '+r.id,'is-success');step(1);f.reset();chosenTime='';date.value='';renderCal();f.querySelector('.hmn-ea-slots').innerHTML='<p>یک روز را از تقویم انتخاب کنید.</p>'}).catch(e=>msg(e.message,'is-error')).finally(()=>b.disabled=false)})})();</script>
