ns[f.elements.provider_id.selectedIndex].text:'پزشک مجموعه';f.querySelector('.hmn-ea-summary').innerHTML='نام: '+f.elements.first_name.value+' '+f.elements.last_name.value+'<br>سرویس: '+sn+'<br>پزشک: '+p+'<br>زمان: '+selected.textContent+' '+month.textContent+' — '+f.querySelector('.hmn-ea-slot.is-selected').textContent},0)})})();</script>
<style>
