	public function bootstrap_ajax() { $this->verify(); $services = self::request( 'GET', 'services' ); $providers = self::request( 'GET', 'providers' ); if ( is_wp_error( $services ) ) { $this->error( $services ); } if ( is_wp_error( $providers ) ) { $this->error( $providers ); } wp_send_json_success( array( 'services' => $services, 'providers' => $providers ) ); }
	public function slots_ajax() { $this->verify(); $service = absint( $_POST['service_id'] ?? 0 ); $provider = absint( $_POST['provider_id'] ?? 0 ); $date = sanitize_text_field( wp_unslash( $_POST['date'] ?? '' ) ); if ( ! $service || ! $provider || ! preg_match( '/^\d{4}-\d{2}-\d{2}$/', $date ) ) { wp_send_json_error( array( 'message' => 'اطلاعات انتخاب نوبت کامل نیست.' ), 400 ); } $slots = self::request( 'GET', 'availabilities', null, array( 'serviceId' => $service, 'providerId' => $provider, 'date' => $date ) ); if ( is_wp_error( $slots ) ) { $this->error( $slots ); } wp_send_json_success( array( 'slots' => $slots ) ); }
	public function verify_otp_ajax() {
		$this->verify();
		$phone = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['user_phone'] ?? '' ) ) );
		$otp = sanitize_text_field( wp_unslash( $_POST['otp_code'] ?? '' ) );
		$stored = get_transient( 'hmn_crm_otp_' . md5( $phone ) );
		if ( ! preg_match( '/^09\d{9}$/', $phone ) || ! $stored || ! hash_equals( (string) $stored, $otp ) ) {
			wp_send_json_error( array( 'message' => 'کد تأیید اشتباه است یا منقضی شده است.' ), 403 );
		}
		wp_send_json_success();
	}

	/** Save CRM-only customer fields. */
	public function customer_meta_save_ajax() {
		if ( ! current_user_can( 'manage_options' ) || ! check_ajax_referer( 'hmn_ea_operator_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'دسترسی نامعتبر است.' ), 403 ); }
		$id = absint( $_POST['customer_id'] ?? 0 ); $file = sanitize_text_field( wp_unslash( $_POST['file_number'] ?? '' ) ); $national = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['national_id'] ?? '' ) ) );
		if ( ! $id || ( $national && ! preg_match( '/^\d{10}$/', $national ) ) ) { wp_send_json_error( array( 'message' => 'شماره پرونده یا شماره ملی معتبر نیست.' ), 400 ); }
		global $wpdb; $table = $wpdb->prefix . 'hmn_crm_customer_meta';
		$wpdb->replace( $table, array( 'customer_id' => $id, 'file_number' => $file, 'national_id' => $national, 'updated_at' => current_time( 'mysql' ) ), array( '%d', '%s', '%s', '%s' ) );
		wp_send_json_success();
	}

	/** Return appointment history (not clinical visit records) for a customer phone number. */
	public function customer_history_ajax() {
		if ( ! current_user_can( 'manage_options' ) || ! check_ajax_referer( 'hmn_ea_operator_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'دسترسی نامعتبر است.' ), 403 ); }
		$phone = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['phone'] ?? '' ) ) );
		if ( ! preg_match( '/^09\d{9}$/', $phone ) ) { wp_send_json_error( array( 'message' => 'شماره تلفن معتبر نیست.' ), 400 ); }
		$rows = self::request( 'GET', 'appointments', null, array( 'from' => '2000-01-01', 'till' => '2100-01-01', 'with' => 'customer,service', 'aggregates' => 1, 'length' => 500 ) );
		if ( is_wp_error( $rows ) ) { $this->error( $rows ); }
		$history = array();
		foreach ( $rows as $row ) { $customer = is_array( $row['customer'] ?? null ) ? $row['customer'] : array(); $customer_phone = preg_replace( '/\D+/', '', (string) ( $customer['phone'] ?? ( $customer['phone_number'] ?? '' ) ) ); if ( $phone !== $customer_phone ) { continue; } $start = (string) ( $row['start'] ?? ( $row['start_datetime'] ?? '' ) ); $service = is_array( $row['service'] ?? null ) ? $row['service'] : array(); $history[] = array( 'id' => absint( $row['id'] ?? 0 ), 'date' => self::jalali_date( substr( $start, 0, 10 ) ), 'time' => substr( $start, 11, 5 ), 'service' => sanitize_text_field( $service['name'] ?? '' ), 'status' => sanitize_text_field( $row['status'] ?? '' ) ); }
		usort( $history, function( $a, $b ) { return $b['id'] <=> $a['id']; } );
		wp_send_json_success( array( 'history' => $history ) );
	}

	/** Cancel an appointment in Easy!Appointments and notify the customer with the cancellation pattern. */
	public function cancel_appointment_ajax() {
		if ( ! current_user_can( 'manage_options' ) || ! check_ajax_referer( 'hmn_ea_operator_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'دسترسی نامعتبر است.' ), 403 ); }
		$id = absint( $_POST['appointment_id'] ?? 0 ); $silent = ! empty( $_POST['silent'] );
		if ( ! $id ) { wp_send_json_error( array( 'message' => 'شناسه نوبت نامعتبر است.' ), 400 ); }
		$appointment = self::request( 'GET', 'appointments/' . $id ); if ( is_wp_error( $appointment ) ) { $this->error( $appointment ); }
		$customer_id = absint( $appointment['customerId'] ?? 0 ); $start = (string) ( $appointment['start'] ?? '' );
		if ( ! $silent && $customer_id ) { $customer = self::request( 'GET', 'customers/' . $customer_id ); if ( ! is_wp_error( $customer ) ) { $phone = preg_replace( '/\D+/', '', (string) ( $customer['phone'] ?? ( $customer['phone_number'] ?? '' ) ) ); $name = trim( (string) ( $customer['firstName'] ?? ( $customer['first_name'] ?? '' ) ) . ' ' . (string) ( $customer['lastName'] ?? ( $customer['last_name'] ?? '' ) ) ); $sms = get_option( 'hmn_crm_sms_settings', array() ); $body_id = is_array( $sms ) ? absint( $sms['melipayamak_booking_cancel_body_id'] ?? 0 ) : 0; if ( $body_id && $phone ) { ( new HMN_CRM_SMS() )->send_pattern( $phone, $body_id, array( $name, self::jalali_date( substr( $start, 0, 10 ) ), substr( $start, 11, 5 ) ) ); } } }
		$deleted = self::request( 'DELETE', 'appointments/' . $id ); if ( is_wp_error( $deleted ) ) { $this->error( $deleted ); }
		wp_send_json_success();
	}

	/** Create an appointment from the protected operator panel, without OTP. */
	public function operator_customer_ajax() {
		if ( ! current_user_can( 'manage_options' ) || ! check_ajax_referer( 'hmn_ea_operator_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'دسترسی نامعتبر است.' ), 403 ); }
		$phone = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['operator_phone'] ?? '' ) ) );
		if ( ! preg_match( '/^09\d{9}$/', $phone ) ) { wp_send_json_error( array( 'message' => 'شماره تلفن معتبر نیست.' ), 400 ); }
		$customers = self::request( 'GET', 'customers', null, array( 'q' => $phone, 'length' => 100 ) );
		if ( is_wp_error( $customers ) ) { $this->error( $customers ); }
		foreach ( $customers as $customer ) {
			$customer_phone = $customer['phone'] ?? ( $customer['phone_number'] ?? '' );
			if ( $phone === preg_replace( '/\D+/', '', (string) $customer_phone ) ) {
				wp_send_json_success( array( 'found' => true, 'first_name' => sanitize_text_field( $customer['firstName'] ?? ( $customer['first_name'] ?? '' ) ), 'last_name' => sanitize_text_field( $customer['lastName'] ?? ( $customer['last_name'] ?? '' ) ) ) );
			}
		}
		wp_send_json_success( array( 'found' => false ) );
	}

	/** Create an appointment from the protected operator panel, without OTP. */
	public function operator_book_ajax() {
		if ( ! current_user_can( 'manage_options' ) || ! check_ajax_referer( 'hmn_ea_operator_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'دسترسی نامعتبر است.' ), 403 ); }
		$first = sanitize_text_field( wp_unslash( $_POST['first_name'] ?? '' ) ); $last = sanitize_text_field( wp_unslash( $_POST['last_name'] ?? '' ) ); $phone = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['operator_phone'] ?? '' ) ) ); $service = absint( $_POST['service_id'] ?? 0 ); $provider = absint( $_POST['provider_id'] ?? 0 ); $date = sanitize_text_field( wp_unslash( $_POST['appointment_date'] ?? '' ) ); $time = sanitize_text_field( wp_unslash( $_POST['appointment_time'] ?? '' ) );
		if ( ! $first || ! $last || ! preg_match( '/^09\d{9}$/', $phone ) || ! $service || ! $provider || ! preg_match( '/^\d{4}-\d{2}-\d{2}$/', $date ) || ! preg_match( '/^\d{2}:\d{2}$/', $time ) ) { wp_send_json_error( array( 'message' => 'همه اطلاعات نوبت را کامل و صحیح وارد کنید.' ), 400 ); }
		$slots = self::request( 'GET', 'availabilities', null, array( 'serviceId' => $service, 'providerId' => $provider, 'date' => $date ) ); if ( is_wp_error( $slots ) ) { $this->error( $slots ); } if ( ! in_array( $time, $slots, true ) ) { wp_send_json_error( array( 'message' => 'این ساعت دیگر آزاد نیست.' ), 409 ); }
		$customers = self::request( 'GET', 'customers', null, array( 'q' => $phone, 'length' => 100 ) ); if ( is_wp_error( $customers ) ) { $this->error( $customers ); } $customer_id = 0; foreach ( $customers as $customer ) { $customer_phone = $customer['phone'] ?? ( $customer['phone_number'] ?? '' ); if ( preg_replace( '/\D+/', '', (string) $customer_phone ) === $phone ) { $customer_id = absint( $customer['id'] ?? 0 ); break; } }
		if ( ! $customer_id ) { $customer = self::request( 'POST', 'customers', array( 'firstName' => $first, 'lastName' => $last, 'phone' => $phone, 'first_name' => $first, 'last_name' => $last, 'phone_number' => $phone, 'email' => $phone . '@phone.invalid', 'timezone' => 'Asia/Tehran', 'language' => 'english' ) ); if ( is_wp_error( $customer ) ) { $this->error( $customer ); } $customer_id = absint( $customer['id'] ?? 0 ); }
		$service_data = self::request( 'GET', 'services/' . $service ); $duration = is_array( $service_data ) && ! empty( $service_data['duration'] ) ? absint( $service_data['duration'] ) : 15; $start = $date . ' ' . $time . ':00'; $start_date = DateTime::createFromFormat( 'Y-m-d H:i:s', $start, new DateTimeZone( 'Asia/Tehran' ) ); $end = $start_date ? $start_date->modify( '+' . $duration . ' minutes' )->format( 'Y-m-d H:i:s' ) : $start;
		$appointment = self::request( 'POST', 'appointments', array( 'start' => $start, 'end' => $end, 'customerId' => $customer_id, 'providerId' => $provider, 'serviceId' => $service, 'start_datetime' => $start, 'end_datetime' => $end, 'id_users_customer' => $customer_id, 'id_users_provider' => $provider, 'id_services' => $service, 'status' => 'Booked' ) ); if ( is_wp_error( $appointment ) ) { $this->error( $appointment ); }
		$sms = get_option( 'hmn_crm_sms_settings', array() ); $body_id = is_array( $sms ) ? absint( $sms['melipayamak_booking_body_id'] ?? 0 ) : 0; if ( $body_id ) { ( new HMN_CRM_SMS() )->send_pattern( $phone, $body_id, array( trim( $first . ' ' . $last ), self::jalali_date( $date ), $time ) ); }
		wp_send_json_success( array( 'id' => absint( $appointment['id'] ?? 0 ) ) );
	}

	public function book_ajax() {
		$this->verify(); $first = sanitize_text_field( wp_unslash( $_POST['first_name'] ?? '' ) ); $last = sanitize_text_field( wp_unslash( $_POST['last_name'] ?? '' ) ); $phone = preg_replace( '/\D+/', '', sanitize_text_field( wp_unslash( $_POST['user_phone'] ?? '' ) ) ); $otp = sanitize_text_field( wp_unslash( $_POST['otp_code'] ?? '' ) ); $service = absint( $_POST['service_id'] ?? 0 ); $provider = absint( $_POST['provider_id'] ?? 0 ); $date = sanitize_text_field( wp_unslash( $_POST['appointment_date'] ?? '' ) ); $time = sanitize_text_field( wp_unslash( $_POST['appointment_time'] ?? '' ) );
		if ( ! $first || ! $last || ! preg_match( '/^09\d{9}$/', $phone ) || ! $service || ! $provider || ! preg_match( '/^\d{4}-\d{2}-\d{2}$/', $date ) || ! preg_match( '/^\d{2}:\d{2}$/', $time ) ) { wp_send_json_error( array( 'message' => 'همه فیلدهای نوبت را کامل و صحیح وارد کنید.' ), 400 ); }
		$stored = get_transient( 'hmn_crm_otp_' . md5( $phone ) ); if ( ! $stored || ! hash_equals( (string) $stored, $otp ) ) { wp_send_json_error( array( 'message' => 'کد تأیید اشتباه است یا منقضی شده است.' ), 403 ); }
		$slots = self::request( 'GET', 'availabilities', null, array( 'serviceId' => $service, 'providerId' => $provider, 'date' => $date ) ); if ( is_wp_error( $slots ) ) { $this->error( $slots ); } if ( ! in_array( $time, $slots, true ) ) { wp_send_json_error( array( 'message' => 'این زمان دیگر در دسترس نیست؛ لطفاً زمان دیگری انتخاب کنید.' ), 409 ); }
		$customers = self::request( 'GET', 'customers', null, array( 'q' => $phone, 'length' => 100 ) ); if ( is_wp_error( $customers ) ) { $this->error( $customers ); } $customer_id = 0; foreach ( $customers as $customer ) { if ( isset( $customer['phone'] ) && preg_replace( '/\D+/', '', (string) $customer['phone'] ) === $phone ) { $customer_id = absint( $customer['id'] ); break; } }
		if ( ! $customer_id ) { $customer = self::request( 'POST', 'customers', array( 'firstName' => $first, 'lastName' => $last, 'phone' => $phone, 'first_name' => $first, 'last_name' => $last, 'phone_number' => $phone, 'email' => $phone . '@phone.invalid', 'timezone' => 'Asia/Tehran', 'language' => 'english' ) ); if ( is_wp_error( $customer ) ) { $this->error( $customer ); } $customer_id = absint( $customer['id'] ?? 0 ); }
		$service_data = self::request( 'GET', 'services/' . $service );
		$duration = is_array( $service_data ) && ! empty( $service_data['duration'] ) ? absint( $service_data['duration'] ) : 15;
		$start = $date . ' ' . $time . ':00';
		$start_date = DateTime::createFromFormat( 'Y-m-d H:i:s', $start, new DateTimeZone( 'Asia/Tehran' ) );
		$end = $start_date ? $start_date->modify( '+' . $duration . ' minutes' )->format( 'Y-m-d H:i:s' ) : $start;
		$appointment = self::request( 'POST', 'appointments', array( 'start' => $start, 'end' => $end, 'customerId' => $customer_id, 'providerId' => $provider, 'serviceId' => $service, 'start_datetime' => $start, 'end_datetime' => $end, 'id_users_customer' => $customer_id, 'id_users_provider' => $provider, 'id_services' => $service, 'status' => 'Booked' ) ); if ( is_wp_error( $appointment ) ) { $this->error( $appointment ); } delete_transient( 'hmn_crm_otp_' . md5( $phone ) );
		$sms = get_option( 'hmn_crm_sms_settings', array() ); $body_id = is_array( $sms ) ? absint( $sms['melipayamak_booking_body_id'] ?? 0 ) : 0; if ( $body_id ) { ( new HMN_CRM_SMS() )->send_pattern( $phone, $body_id, array( trim( $first . ' ' . $last ), self::jalali_date( $date ), $time ) ); }
		wp_send_json_success( array( 'id' => absint( $appointment['id'] ?? 0 ) ) );
	}
	public static function appointments( $from, $till ) {
		$rows = self::request( 'GET', 'appointments', null, array( 'from' => $from, 'till' => $till, 'with' => 'customer,service,provider', 'aggregates' => 1, 'length' => 200 ) );
		if ( is_wp_error( $rows ) || ! is_array( $rows ) ) { return $rows; }
		$normalized = array();
		foreach ( $rows as $row ) {
			if ( ! is_array( $row ) ) { continue; }
			$customer = isset( $row['customer'] ) && is_array( $row['customer'] ) ? $row['customer'] : array();
			$service = isset( $row['service'] ) && is_array( $row['service'] ) ? $row['service'] : array();
			$normalized[] = array( 'id' => absint( $row['id'] ?? 0 ), 'appointment_date' => substr( (string) ( $row['start'] ?? ( $row['start_datetime'] ?? '' ) ), 0, 10 ), 'appointment_time' => substr( (string) ( $row['start'] ?? ( $row['start_datetime'] ?? '' ) ), 11, 5 ), 'field_name' => sanitize_text_field( $customer['firstName'] ?? ( $customer['first_name'] ?? '' ) ), 'field_lname' => sanitize_text_field( $customer['lastName'] ?? ( $customer['last_name'] ?? '' ) ), 'user_phone' => sanitize_text_field( $customer['phone'] ?? ( $customer['phone_number'] ?? '' ) ), 'service_title' => sanitize_text_field( $service['name'] ?? ( $row['service_name'] ?? '' ) ) );
		}
		usort( $normalized, function( $a, $b ) { return strcmp( $a['appointment_time'], $b['appointment_time'] ); } );
		return $normalized;
	}
	private function verify() { if ( ! check_ajax_referer( 'hmn_ea_booking', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'درخواست نامعتبر است.' ), 403 ); } }
	private static function jalali_date( $date ) { $time = strtotime( $date ); $gy = (int) wp_date( 'Y', $time ); $gm = (int) wp_date( 'n', $time ); $gd = (int) wp_date( 'j', $time ); $gdm = array( 0,31,59,90,120,151,181,212,243,273,304,334 ); $jy = $gy > 1600 ? 979 : 0; $gy -= $gy > 1600 ? 1600 : 621; $gy2 = $gm > 2 ? $gy + 1 : $gy; $days = 365 * $gy + (int) floor( ( $gy2 + 3 ) / 4 ) - (int) floor( ( $gy2 + 99 ) / 100 ) + (int) floor( ( $gy2 + 399 ) / 400 ) - 80 + $gd + $gdm[ $gm - 1 ]; $jy += 33 * (int) floor( $days / 12053 ); $days %= 12053; $jy += 4 * (int) floor( $days / 1461 ); $days %= 1461; if ( $days > 365 ) { $jy += (int) floor( ( $days - 1 ) / 365 ); $days = ( $days - 1 ) % 365; } $jm = $days < 186 ? 1 + (int) floor( $days / 31 ) : 7 + (int) floor( ( $days - 186 ) / 30 ); $jd = 1 + ( $days < 186 ? $days % 31 : ( $days - 186 ) % 30 ); return sprintf( '%04d/%02d/%02d', $jy, $jm, $jd ); }
	private function error( $e ) { wp_send_json_error( array( 'message' => $e->get_error_message() ), (int) ( $e->get_error_data()['status'] ?? 502 ) ); }
}
new HMN_CRM_EasyAppointments();
